const state={local:[],remote:[],tools:[],view:'all',category:'',query:'',type:'',source:'',sort:'name',selected:new Set(),pendingReplace:false,pendingRestoreOriginal:null,settings:{theme:'system',density:'comfortable',syncEnabled:true,syncInterval:15,portableAutoSync:true,portableKeepBackups:true,portableFolderFallback:true},categoryNodes:[],collectionIds:null,collectionName:'',pendingImport:null};
const $=id=>document.getElementById(id); const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function hostname(url){try{return new URL(url).hostname.replace(/^www\./,'')}catch{return ''}}
function favicon(url){const h=hostname(url);return h?`https://www.google.com/s2/favicons?domain=${encodeURIComponent(h)}&sz=64`:''}
function normalizeUrl(url){try{const u=new URL(String(url||'').trim());u.hash='';u.protocol=u.protocol.toLowerCase();u.hostname=u.hostname.toLowerCase().replace(/^www\./,'');if((u.protocol==='https:'&&u.port==='443')||(u.protocol==='http:'&&u.port==='80'))u.port='';u.pathname=u.pathname.replace(/\/{2,}/g,'/').replace(/\/$/,'')||'/';return u.toString().replace(/\/$/,'')}catch{return String(url||'').trim().replace(/\/$/,'')}}
const unique=a=>[...new Set((a||[]).filter(Boolean))];
function norm(raw,source='local'){return{id:raw.id||uid(),name:String(raw.name||'Untitled').trim(),url:String(raw.url||'').trim(),category:String(raw.category||'Uncategorized').trim()||'Uncategorized',type:String(raw.type||'Website'),tags:Array.isArray(raw.tags)?unique(raw.tags.map(String).map(x=>x.trim())):[],description:String(raw.description||'').trim(),notes:String(raw.notes||'').trim(),favorite:Boolean(raw.favorite),usageCount:Number(raw.usageCount||0),lastUsed:Number(raw.lastUsed||0),addedAt:Number(raw.addedAt||Date.now()),lastModified:Number(raw.lastModified||Date.now()),subcategory:String(raw.subcategory||''),subcategoryId:raw.subcategoryId||'',categoryId:raw.categoryId||'',displayId:raw.displayId||'',smartLabels:Array.isArray(raw.smartLabels)?raw.smartLabels:[],aliases:Array.isArray(raw.aliases)?raw.aliases:[],collections:Array.isArray(raw.collections)?raw.collections:[],priority:raw.priority||'normal',source}};
function enrich(x){if(!x.description)x.description=`${x.category||'Online'} resource: ${x.name}. Useful for quick access from your personal tool archive.`;if(!x.tags?.length)x.tags=unique([...(x.name||'').toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>2).slice(0,3),...(x.category||'').toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>2).slice(0,2)]);return x}
function map(list){const m=new Map();for(const r of list){const x=norm(r),k=window.CMJAdvanced?.exactUrl(x.url)||normalizeUrl(x.url);if(k&&!m.has(k))m.set(k,x)}return m}
function dedupe(list){const m=new Map(),out=[];let removed=0;for(const raw of list||[]){const x=enrich(norm(raw,'local')),k=window.CMJAdvanced?.exactUrl(x.url)||normalizeUrl(x.url);if(!k)continue;if(!m.has(k)){m.set(k,x);out.push(x)}else{removed++;const o=m.get(k);o.tags=unique([...o.tags,...x.tags]);if(!o.description||o.description.includes('Useful for quick access'))o.description=x.description;if(!o.notes)o.notes=x.notes;o.favorite||=x.favorite;o.usageCount=Math.max(o.usageCount,x.usageCount);o.lastUsed=Math.max(o.lastUsed,x.lastUsed)}}return{tools:out,removed}}
function sourceBadge(x){return x.source==='both'?'<span class="source-badge both">🏠 LOCAL + ☁️ REMOTE</span>':x.source==='remote'?'<span class="source-badge remote">☁️ REMOTE</span>':'<span class="source-badge local">🏠 LOCAL</span>'}
function categories(){return unique([...state.local.map(x=>x.category||'Uncategorized'),...(state.categoryNodes||[]).filter(c=>!c.parentId).map(c=>c.name)]).sort((a,b)=>a.localeCompare(b))}
function buildUnified(){const lm=map(state.local),rm=map(state.remote),out=[];const keys=new Set([...lm.keys(),...rm.keys()]);for(const k of keys){const l=lm.get(k),r=rm.get(k);if(l&&r){const x={...l,source:'both',remote:r};x.tags=unique([...l.tags,...r.tags]);x.description=l.description&&!l.description.includes('Useful for quick access')?l.description:(r.description||l.description);out.push(x)}else if(l)out.push({...l,source:'local'});else if(r)out.push({...r,id:`remote:${r.id}`,source:'remote',favorite:false,notes:'',usageCount:0})}state.tools=out}
async function syncPortableNow(manualBackup=false){if(!window.CMJPortable||state.settings.portableAutoSync===false)return {ok:false,configured:false};try{return await CMJPortable.sync({tools:state.local,remote:state.remote,settings:state.settings,categories:window.CMJAdvanced?await CMJAdvanced.categories():state.categoryNodes,collections:window.CMJAdvanced?await CMJAdvanced.collections():[],manualBackup})}catch(err){console.warn('Portable JSON sync deferred:',err.message);return {ok:false,error:err.message}}}
async function saveLocal(){const d=dedupe(state.local);state.local=d.tools;if(window.CMJAdvanced){await CMJAdvanced.syncTools(state.local);state.categoryNodes=await CMJAdvanced.categories()}await chrome.storage.local.set({localLibrary:state.local,settings:state.settings});await syncPortableNow()}
async function readBundledPortableProfile(){
  // This file is populated on PC1 by the Native Messaging helper when its root is
  // configured to the extension's user-data directory. A copied unpacked folder
  // then carries the profile to PC2. Packaged defaults remain read-only.
  try{const url=chrome.runtime.getURL('user-data/profile-data.json');const response=await fetch(url,{cache:'no-store'});if(!response.ok)return null;const profile=await response.json();return profile&&Array.isArray(profile.localLibrary)?profile:null}
  catch(err){console.warn('Bundled portable profile unavailable:',err.message);return null}
}
async function load(){
  const r=await chrome.storage.local.get(['localLibrary','remoteLibrary','settings']);
  let legacy=dedupe(Array.isArray(r.localLibrary)?r.localLibrary:[]).tools;
  if(window.CMJDatabase){try{const db=await CMJDatabase.readAll();if(db.initialized){const indexed=db.records.flatMap(c=>c.tools||[]);if(indexed.length||!legacy.length)legacy=dedupe([...indexed,...legacy]).tools;}}catch(err){console.warn('IndexedDB read fallback:',err)}}
  state.local=legacy;state.remote=Array.isArray(r.remoteLibrary)?r.remoteLibrary.map(x=>norm(x,'remote')):[];state.settings={...state.settings,...(r.settings||{})};
  // Restore from the copied extension folder BEFORE ensureInitialized/saveLocal.
  // This prevents the 330 packaged/default-only profile on a new PC from being
  // written over the 395-tool portable profile copied from PC1.
  const bundled=await readBundledPortableProfile();
  if(bundled){
    const before=state.local.length;
    const bundledTools=bundled.localLibrary.map(x=>norm(x,'local'));
    // Merge by normalized URL. Never replace a larger existing local library with a smaller bundle.
    const merged=dedupe([...state.local,...bundledTools]).tools;
    if(merged.length>=state.local.length)state.local=merged;
    if(bundled.settings&&typeof bundled.settings==='object')state.settings={...state.settings,...bundled.settings};
    // Initialize the category store from the merged tool list first; then merge portable category metadata into it.
    // Doing this in the opposite order could let first-run migration overwrite imported category hierarchy.
    if(window.CMJAdvanced)await CMJAdvanced.ensureInitialized(state.local);
    if(window.CMJAdvanced&&Array.isArray(bundled.categories)&&bundled.categories.length){
      const nodes=bundled.categories.slice(),byId=new Map(nodes.map(n=>[n.id,n]));
      const depth=n=>{let d=0,p=n.parentId;while(p&&byId.has(p)&&d<100){d++;p=byId.get(p).parentId}return d};nodes.sort((a,b)=>depth(a)-depth(b));
      const idMap=new Map();
      for(const n of nodes){const parent=n.parentId?nodes.find(x=>x.id===n.parentId):null;const localParent=parent?idMap.get(parent.id):null;const localNode=await CMJAdvanced.ensureCategory(n.name,localParent?.id||null);idMap.set(n.id,localNode)}
      for(const tool of state.local){if(tool.categoryId&&idMap.has(tool.categoryId))tool.categoryId=idMap.get(tool.categoryId).id;if(tool.subcategoryId&&idMap.has(tool.subcategoryId))tool.subcategoryId=idMap.get(tool.subcategoryId).id;}
    }
    if(Array.isArray(bundled.remoteLibrary)){const seen=new Set(state.remote.map(x=>normalizeUrl(x.url)));for(const raw of bundled.remoteLibrary){const item=norm(raw,'remote'),key=normalizeUrl(item.url);if(key&&!seen.has(key)){state.remote.push(item);seen.add(key)}}}
    if(Array.isArray(bundled.collections)&&window.CMJAdvanced){const current=await CMJAdvanced.collections(),all=[...current];for(const c of bundled.collections)if(!all.some(x=>x.id===c.id))all.push(c);await chrome.storage.local.set({cmjCollectionsV6:all});if(window.CMJDatabase)await CMJDatabase.replaceCollections(all)}
    console.info(`Checked bundled profile before first save: ${before} → ${state.local.length} local tools; bundled profile has ${bundled.localLibrary.length}`);
    if(bundled.localLibrary.length===0)console.info('No personal portable profile is bundled yet. On PC1 select the unpacked extension root and run Portable Database → Sync Now before copying the folder.');
  }
  if(window.CMJAdvanced){await CMJAdvanced.ensureInitialized(state.local);await CMJAdvanced.syncTools(state.local);state.categoryNodes=await CMJAdvanced.categories()}
  await saveLocal();buildUnified();applySettings();render();await updateSyncStatus();setTimeout(syncGithub,500)
}
async function refresh(){const r=await chrome.storage.local.get(['localLibrary','remoteLibrary','settings']);state.local=dedupe(r.localLibrary||[]).tools;state.remote=(r.remoteLibrary||[]).map(x=>norm(x,'remote'));state.settings={...state.settings,...(r.settings||{})};if(window.CMJAdvanced)state.categoryNodes=await CMJAdvanced.categories();buildUnified();applySettings();render()}
async function syncGithub(){try{const r=await chrome.runtime.sendMessage({type:'sync-github'});await refresh();await syncPortableNow();await updateSyncStatus();if(r?.ok)toast(`GitHub sync: +${r.added} new · ${r.updated} updated · ${r.removed} remote removed`);else toast('GitHub sync: '+(r?.error||'failed'))}catch(e){toast('GitHub sync unavailable')}}
function applySettings(){const dark=state.settings.theme==='dark'||(state.settings.theme==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('dark',dark);$('grid').classList.toggle('compact',state.settings.density==='compact');$('theme').value=state.settings.theme;$('density').value=state.settings.density;$('sync-enabled').value=String(state.settings.syncEnabled!==false);$('sync-interval').value=String(state.settings.syncInterval||15)}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),3200)}
function parseSearch(q){const o={text:[],category:null,subcategory:null,tag:null,favorite:null,type:null,recent:false};const re=/(?:^|\s)(category|subcategory|tag|favorite|type|used):("[^"]+"|\S+)/gi;let m;while((m=re.exec(q)))o[m[1].toLowerCase()]=m[2].replace(/^"|"$/g,'');o.recent=String(o.used||'').toLowerCase()==='recent';o.text=q.replace(re,' ').trim().split(/\s+/).filter(Boolean);return o}
function filtered(){let a=[...state.tools];if(state.view==='favorites')a=a.filter(x=>x.favorite);if(state.view==='recent')a=a.filter(x=>x.lastUsed);if(state.collectionIds)a=a.filter(x=>state.collectionIds.has(x.id));if(state.category)a=a.filter(x=>x.category===state.category);if(state.type)a=a.filter(x=>x.type===state.type);if(state.source)a=a.filter(x=>x.source===state.source);const p=parseSearch(state.query.toLowerCase());if(p.category)a=a.filter(x=>x.category.toLowerCase().includes(p.category.toLowerCase()));if(p.subcategory)a=a.filter(x=>(x.subcategory||'').toLowerCase().includes(p.subcategory.toLowerCase()));if(p.tag)a=a.filter(x=>x.tags.some(t=>t.toLowerCase().includes(p.tag.toLowerCase())));if(p.favorite)a=a.filter(x=>String(x.favorite)===String(p.favorite).toLowerCase());if(p.type)a=a.filter(x=>x.type.toLowerCase()===p.type.toLowerCase());if(p.recent)a=a.filter(x=>x.lastUsed);if(p.text.length)a=a.filter(x=>p.text.every(q=>[x.name,x.url,x.category,x.subcategory,x.description,x.notes,x.tags.join(' '),(x.smartLabels||[]).join(' '),(x.aliases||[]).join(' ')].join(' ').toLowerCase().includes(q)) || (window.CMJAdvanced&&CMJAdvanced.searchScore(x,p.text.join(' '))>0));if(state.sort==='name')a.sort((x,y)=>x.name.localeCompare(y.name));if(state.sort==='category')a.sort((x,y)=>x.category.localeCompare(y.category)||x.name.localeCompare(y.name));if(state.sort==='recent')a.sort((x,y)=>(y.lastUsed||0)-(x.lastUsed||0));if(state.sort==='added')a.sort((x,y)=>(y.addedAt||0)-(x.addedAt||0));return a}
function card(x){const icon=favicon(x.url),tags=x.tags.slice(0,3).map(t=>`<span class="chip">${esc(t)}</span>`).join(''),sel=state.selected.has(x.id);return `<article class="card ${sel?'selected':''}" data-card="${esc(x.id)}"><input class="card-select" type="checkbox" data-select="${esc(x.id)}" ${sel?'checked':''}><div class="card-top" style="padding-left:18px"><div class="favicon">${icon?`<img src="${icon}" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'">`:''}<span class="fallback">${esc(x.name.slice(0,1).toUpperCase())}</span></div><div class="card-title">${esc(x.name)}<div class="card-title-sub">${esc(hostname(x.url))}</div>${sourceBadge(x)}</div><button class="star ${x.favorite?'on':''}" data-id="${esc(x.id)}">★</button></div><div class="desc">${esc(x.description)}</div><div class="chips"><span class="chip category-chip">${esc(x.category)}</span>${tags}</div><div class="card-actions"><button class="btn primary" data-open="${esc(x.id)}">Open ↗</button><button class="btn" data-details="${esc(x.id)}">Details</button><button class="btn menu-btn" data-menu="${esc(x.id)}">⋮</button></div><div class="card-menu hidden" data-menu-box="${esc(x.id)}"><button data-menu-action="details" data-id="${esc(x.id)}">◉ View Details</button><button data-menu-action="edit" data-id="${esc(x.id)}">✎ Edit / Update</button><button data-menu-action="favorite" data-id="${esc(x.id)}">★ ${x.favorite?'Remove Favorite':'Add to Favorites'}</button><button data-menu-action="category" data-id="${esc(x.id)}">▣ Move Category</button><button data-menu-action="open" data-id="${esc(x.id)}">↗ Open Tool</button>${x.source==='remote'?'<button data-menu-action="copy" data-id="'+esc(x.id)+'">＋ Create Local Copy</button>':''}<button class="danger-item" data-menu-action="delete" data-id="${esc(x.id)}">⌫ Remove Local Record</button></div></article>`}
function render(){buildUnified();renderSidebar();const a=filtered();$('view-title').textContent=state.collectionName||state.category||({all:'All Tools',favorites:'Favorites',recent:'Recently Used'}[state.view]||'All Tools');$('view-count').textContent=`${a.length} tool${a.length===1?'':'s'}`;$('grid').innerHTML=a.map(card).join('');$('empty').classList.toggle('hidden',!a.length);$('stat-tools').textContent=state.tools.length;$('stat-categories').textContent=categories().length;$('stat-favorites').textContent=state.local.filter(x=>x.favorite).length;$('stat-recent').textContent=state.local.filter(x=>x.lastUsed).length;$('bulkbar').classList.toggle('hidden',!state.selected.size);$('selected-count').textContent=state.selected.size;document.querySelectorAll('.star').forEach(b=>b.onclick=()=>toggleFav(b.dataset.id));document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openTool(b.dataset.open));document.querySelectorAll('[data-details]').forEach(b=>b.onclick=()=>showDetails(b.dataset.details));document.querySelectorAll('[data-menu]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleMenu(b.dataset.menu)});document.querySelectorAll('[data-menu-action]').forEach(b=>b.onclick=e=>{e.stopPropagation();menuAction(b.dataset.menuAction,b.dataset.id)});document.querySelectorAll('[data-select]').forEach(b=>b.onchange=()=>{b.checked?state.selected.add(b.dataset.select):state.selected.delete(b.dataset.select);render()});document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.cat;state.view='all';render()})}
function renderSidebar(){$('category-list').innerHTML=categories().map(c=>`<button class="category-item ${state.category===c?'selected':''}" data-cat="${esc(c)}"><span>${esc(c)}</span><b>${state.local.filter(x=>x.category===c).length}</b></button>`).join('');$('count-all').textContent=state.tools.length;$('count-fav').textContent=state.local.filter(x=>x.favorite).length;$('count-recent').textContent=state.local.filter(x=>x.lastUsed).length}
function toggleMenu(id){document.querySelectorAll('.card-menu').forEach(m=>m.classList.toggle('hidden',m.dataset.menuBox!==id||!m.classList.contains('hidden')))}function closeMenus(){document.querySelectorAll('.card-menu').forEach(m=>m.classList.add('hidden'))}
async function openTool(id){const x=state.tools.find(t=>t.id===id);if(!x)return;try{await chrome.tabs.create({url:/^https?:\/\//i.test(x.url)?x.url:'https://'+x.url});const l=state.local.find(t=>normalizeUrl(t.url)===normalizeUrl(x.url));if(l){l.lastUsed=Date.now();l.usageCount=(l.usageCount||0)+1;l.lastModified=Date.now();await saveLocal();render()}toast('Opened '+x.name)}catch{toast('Could not open tool')}}
async function ensureLocal(x){let l=state.local.find(t=>normalizeUrl(t.url)===normalizeUrl(x.url));if(!l){l=norm({...x,id:uid(),source:'local',favorite:false,notes:''},'local');state.local.push(l);await saveLocal();render();toast('Created local copy')}return l}
async function toggleFav(id){const x=state.tools.find(t=>t.id===id);if(!x)return;const l=await ensureLocal(x);l.favorite=!l.favorite;l.lastModified=Date.now();await saveLocal();render()}
function showDetails(id){const x=state.tools.find(t=>t.id===id);if(!x)return;$('details-title').textContent=x.name;$('details-name').textContent=x.name;$('details-url').textContent=x.url;$('details-url').href=x.url;$('details-url-code').textContent=x.url;$('details-category').textContent=x.subcategory?`${x.category} / ${x.subcategory}`:x.category;$('details-type').textContent=x.type;$('details-description').textContent=x.description||'No description added.';$('details-notes').textContent=x.notes||'No personal notes added.';$('details-tags').innerHTML=x.tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')||'<span class="muted">No tags</span>';$('details-usage').textContent=x.lastUsed?`Opened ${new Date(x.lastUsed).toLocaleString()} · ${x.usageCount||0} recorded opens`:'Not opened yet';const f=favicon(x.url);$('details-favicon').src=f||'';$('details-favicon').style.display=f?'block':'none';$('details-fallback').textContent=x.name.slice(0,1).toUpperCase();$('details-fallback').style.display=f?'none':'grid';$('details-source').innerHTML=sourceBadge(x);$('details-open').onclick=()=>{closeDetails();openTool(x.id)};$('details-edit').onclick=()=>{closeDetails();editTool(x.id)};$('details-favorite').textContent=x.favorite?'★ Remove Favorite':'★ Add to Favorites';$('details-favorite').onclick=async()=>{await toggleFav(x.id);showDetails(id)};$('details-delete').onclick=async()=>{const l=state.local.find(t=>normalizeUrl(t.url)===normalizeUrl(x.url));if(!l)return toast('Remote-only tool: create a local copy before removing or customizing it.');if(confirm(`Remove local record "${x.name}"?`)){state.local=state.local.filter(t=>t.id!==l.id);await saveLocal();closeDetails();render();toast('Local record removed')}};$('details-modal').classList.remove('hidden')}
function closeDetails(){$('details-modal').classList.add('hidden')}
function openModal(tool=null){$('modal').classList.remove('hidden');$('modal-title').textContent=tool?'Edit / Update Tool':'Add Tool';$('tool-id').value=tool?.id||'';$('tool-name').value=tool?.name||'';$('tool-url').value=tool?.url||'';$('tool-category').value=tool?.category||'';$('tool-type').value=tool?.type||'Website';$('tool-tags').value=(tool?.tags||[]).join(', ');$('tool-subcategory').value=tool?.subcategory||'';$('tool-aliases').value=(tool?.aliases||[]).join(', ');$('tool-smart-labels').value=(tool?.smartLabels||[]).join(', ');$('tool-description').value=tool?.description||'';$('tool-notes').value=tool?.notes||'';$('delete-tool').classList.toggle('hidden',!tool);checkUrl();suggestTags()}
function closeModal(){$('modal').classList.add('hidden');$('category-suggestions').classList.add('hidden')}
function editTool(id){const x=state.tools.find(t=>t.id===id);if(!x)return;if(x.source==='remote')return ensureLocal(x).then(l=>openModal(l));openModal(state.local.find(t=>t.id===id)||state.local.find(t=>normalizeUrl(t.url)===normalizeUrl(x.url)))}
function findDuplicate(url,ignoreId=''){const k=CMJAdvanced.exactUrl(url);return state.tools.find(x=>CMJAdvanced.exactUrl(x.url)===k&&x.id!==ignoreId)}
function checkUrl(){const box=$('duplicate-box'),x=findDuplicate($('tool-url').value,$('tool-id').value);if(x){box.innerHTML=`<div class="warning-box">⚠️ <strong>Website already exists</strong> — ${esc(x.name)} · ${sourceBadge(x)} <button class="btn" data-jump="${esc(x.id)}">View Existing</button></div>`;box.classList.remove('hidden');box.querySelector('[data-jump]').onclick=()=>{closeModal();showDetails(x.id)}}else{box.classList.add('hidden');box.innerHTML=''};similarCheck()}
function similarCheck(){
  const url=$('tool-url').value.trim(),name=$('tool-name').value.trim(),box=$('similar-box');
  if(!url){box.classList.add('hidden');return}
  const matches=state.tools.filter(x=>x.id!==$('tool-id').value).map(x=>({x,urlScore:CMJAdvanced.urlSimilarity(url,x.url),nameScore:CMJAdvanced.similarity(name,x.name)}))
    .filter(v=>v.urlScore>=25||v.nameScore>=65).sort((a,b)=>(b.urlScore*.8+b.nameScore*.2)-(a.urlScore*.8+a.nameScore*.2)).slice(0,4);
  box.innerHTML=matches.length?`<div class="warning-box"><strong>🔎 Similarity review — not an automatic duplicate block</strong>${matches.map(v=>`<div style="margin-top:8px"><b>${esc(v.x.name)}</b> · URL ${v.urlScore}% · Name ${v.nameScore}%<div class="similarity-meter"><span style="width:${v.urlScore}%"></span></div><small>${esc(v.x.url)}</small></div>`).join('')}<p>Different paths and query parameters can represent different tools. You can still save this record.</p></div>`:'';
  box.classList.toggle('hidden',!matches.length);
}
function categorySuggest(){const q=$('tool-category').value.toLowerCase();const arr=categories().filter(c=>c.toLowerCase().includes(q)).slice(0,8);$('category-suggestions').innerHTML=arr.map(c=>`<button class="suggestion" data-catpick="${esc(c)}"><span>📁 ${esc(c)}</span><small>${state.local.filter(x=>x.category===c).length} tools</small></button>`).join('')+`<button class="suggestion" data-catnew="1"><span>＋ Create New Category</span><small>${esc($('tool-category').value||'')}</small></button>`;$('category-suggestions').classList.toggle('hidden',!q&&!arr.length);document.querySelectorAll('[data-catpick]').forEach(b=>b.onclick=()=>{$('tool-category').value=b.dataset.catpick;$('category-suggestions').classList.add('hidden')})}
