 const clean=dedupe(items).tools,existing=new Set(state.local.map(x=>CMJAdvanced.exactUrl(x.url)));
 const fresh=clean.filter(x=>!existing.has(CMJAdvanced.exactUrl(x.url)));
 const comparisons=fresh.map(x=>({tool:x,match:state.local.map(old=>({old,url:CMJAdvanced.urlSimilarity(x.url,old.url),name:CMJAdvanced.similarity(x.name,old.name)})).filter(v=>v.url>=25||v.name>=65).sort((a,b)=>b.url-a.url)[0]}));
 state.pendingImport=fresh;
 const similar=comparisons.filter(x=>x.match).length;
 $('preview-summary').innerHTML=`<div class="health-grid"><div class="health-stat"><b>${clean.length}</b><span>Found</span></div><div class="health-stat"><b>${fresh.length}</b><span>New local</span></div><div class="health-stat"><b>${clean.length-fresh.length}</b><span>Exact duplicates</span></div><div class="health-stat"><b>${similar}</b><span>Similarity warnings</span></div></div><p class="muted">${esc(label)} · Similar URLs are warnings only and will not be silently discarded.</p>`;
