async function mergePortableProfile(profile,{restoreSettings=false}={}){
 if(!profile||!Array.isArray(profile.localLibrary))throw new Error('Portable profile is missing a valid localLibrary array.');
 const before=state.local.length;
 state.local=dedupe([...state.local,...profile.localLibrary.map(x=>norm(x,'local'))]).tools;
 const remoteMap=new Map(state.remote.map(x=>[normalizeUrl(x.url),x]));
 for(const raw of (Array.isArray(profile.remoteLibrary)?profile.remoteLibrary:[])){const x=norm(raw,'remote'),key=normalizeUrl(x.url);if(key&&!remoteMap.has(key)){remoteMap.set(key,x);state.remote.push(x)}}
 if(Array.isArray(profile.categories)&&window.CMJAdvanced){
  const nodes=profile.categories.slice(),byId=new Map(nodes.map(n=>[n.id,n])),depth=n=>{let d=0,p=n.parentId;while(p&&byId.has(p)&&d<100){d++;p=byId.get(p).parentId}return d};
  nodes.sort((a,b)=>depth(a)-depth(b));const idMap=new Map();
  for(const n of nodes){const parent=n.parentId?nodes.find(x=>x.id===n.parentId):null;const localParent=parent?idMap.get(parent.id):null;const created=await CMJAdvanced.ensureCategory(n.name,localParent?.id||null);idMap.set(n.id,created)}
  for(const tool of state.local){if(tool.categoryId&&idMap.has(tool.categoryId))tool.categoryId=idMap.get(tool.categoryId).id;if(tool.subcategoryId&&idMap.has(tool.subcategoryId))tool.subcategoryId=idMap.get(tool.subcategoryId).id;}
 }
 if(Array.isArray(profile.collections)&&window.CMJAdvanced){const current=await CMJAdvanced.collections(),merged=[...current];for(const c of profile.collections)if(!merged.some(x=>x.id===c.id))merged.push(c);await chrome.storage.local.set({cmjCollectionsV6:merged});if(window.CMJDatabase)await CMJDatabase.replaceCollections(merged)}
 if(restoreSettings&&profile.settings)state.settings={...state.settings,...profile.settings};
 await chrome.storage.local.set({remoteLibrary:state.remote,settings:state.settings});
 await saveLocal();buildUnified();return {before,after:state.local.length,added:Math.max(0,state.local.length-before)};
}
async function refreshPortableStatus(){if(!window.CMJPortable)return;const s=await CMJPortable.status();const sync=s.sync||{};$('portable-status').textContent=`Folder: ${s.folder} · Status: ${sync.status||'not configured'} · Files: ${sync.fileCount||0} · Last sync: ${sync.lastSync?new Date(sync.lastSync).toLocaleString():'Never'}${sync.error?' · Error: '+sync.error:''}`;$('portable-native-path').value=state.settings.portableNativePath||'';$('portable-native-enabled').value=String(!!state.settings.portableNativeEnabled);$('portable-auto-sync').value=String(state.settings.portableAutoSync!==false);if($('portable-folder-fallback'))$('portable-folder-fallback').checked=state.settings.portableFolderFallback!==false}
