$('database-zip').onchange=async e=>{
 const f=e.target.files[0];if(!f)return;
 try{
  const entries=await CMJZip.read(await f.arrayBuffer()),json=entries.filter(x=>x.name.toLowerCase().endsWith('.json')&&!x.name.includes('..'));
  const imported=[],idMap=new Map(),catsEntry=json.find(x=>x.name.endsWith('categories-index.json'));
  if(catsEntry){const d=JSON.parse(catsEntry.text()),nodes=(d.categories||[]).slice().sort((a,b)=>String(a.displayId||'').split('-').length-String(b.displayId||'').split('-').length);
    for(const n of nodes){const parent=nodes.find(p=>p.id===n.parentId);const localParent=parent?await CMJAdvanced.ensureCategory(parent.name):null;const local=await CMJAdvanced.ensureCategory(n.name,localParent?.id||null);idMap.set(n.id,local.id)}
  }
  for(const entry of json){if(entry.name.endsWith('categories-index.json')||entry.name.endsWith('database-config.json')||entry.name.endsWith('backup-manifest.json')||entry.name.endsWith('collections.json'))continue;
   const d=JSON.parse(entry.text());for(const t of (d.tools||[])){if(!t.url||!/^https?:\/\//i.test(t.url))continue;const dup=state.local.some(x=>CMJAdvanced.exactUrl(x.url)===CMJAdvanced.exactUrl(t.url));if(!dup)imported.push(norm({...t,id:t.id||uid(),categoryId:idMap.get(t.categoryId)||undefined,subcategoryId:idMap.get(t.subcategoryId)||undefined},'local'))}
  }
  if(!imported.length){toast('ZIP contained no new valid tools');return}
  await prepareImport(imported,`ZIP database import · ${f.name}`);
 }catch(err){toast('ZIP import failed: '+err.message)}
 e.target.value='';
};

