$('database-folder').onchange=async e=>{
 const fs=[...e.target.files].filter(f=>f.name.toLowerCase().endsWith('.json'));if(!fs.length)return toast('No JSON files found in selected folder');
 const imported=[];let skipped=0;
 try{
  for(const f of fs){const d=JSON.parse(await f.text());const arr=Array.isArray(d)?d:(d.tools||d.database?.tools||[]);
   for(const raw of arr){if(!raw?.url||!/^https?:\/\//i.test(raw.url)){skipped++;continue}
    if(state.local.some(x=>CMJAdvanced.exactUrl(x.url)===CMJAdvanced.exactUrl(raw.url))){skipped++;continue}
    imported.push(norm({...raw,id:raw.id||uid()},'local'));
   }
  }
  if(imported.length)await prepareImport(imported,`Folder import · ${fs.length} JSON files · ${skipped} exact duplicates/invalid skipped`);
  else toast(`No new tools found · ${skipped} skipped`);
 }catch(err){toast('Folder import failed: '+err.message)}
 e.target.value='';
};
$('open-command-center').onclick=()=>{$('settings-modal').classList.add('hidden');$('command-modal').classList.remove('hidden');$('command-search').value='';renderCommands();$('command-search').focus()};
$('close-command').onclick=()=>$('command-modal').classList.add('hidden');
function renderCommands(){
 const q=$('command-search').value.trim(),actions=[['Add a new tool','Open the tool editor',()=>openModal()],['Open Database Manager','Manage categories and backups',()=>$('open-database-manager').click()],['Export full database','Download a complete database JSON',()=>$('db-export-all').click()],['Open Favorites','Show favorite tools',()=>{state.view='favorites';state.category='';$('command-modal').classList.add('hidden');render()}],['Recently Used','Show recently used tools',()=>{state.view='recent';state.category='';$('command-modal').classList.add('hidden');render()}]];
 const actionHtml=actions.map((a,i)=>({a,i})).filter(({a})=>!q||a[0].toLowerCase().includes(q.toLowerCase())||a[1].toLowerCase().includes(q.toLowerCase())).map(({a,i})=>`<button class="command-result" data-command-action="${i}"><span>${esc(a[0])}<small>${esc(a[1])}</small></span><kbd>↵</kbd></button>`).join('');
 const tools=state.tools.map(t=>({t,s:CMJAdvanced.searchScore(t,q)})).filter(x=>q&&x.s>0).sort((a,b)=>b.s-a.s).slice(0,8);
 $('command-results').innerHTML=actionHtml+tools.map(({t})=>`<button class="command-result" data-command-tool="${esc(t.id)}"><span>${esc(t.name)}<small>${esc(t.category)} · ${esc(hostname(t.url))}</small></span><kbd>↗</kbd></button>`).join('')||'<p class="muted">Type to search tools and actions.</p>';
 document.querySelectorAll('[data-command-action]').forEach(b=>b.onclick=()=>actions[Number(b.dataset.commandAction)]?.[2]());
 document.querySelectorAll('[data-command-tool]').forEach(b=>b.onclick=()=>{$('command-modal').classList.add('hidden');openTool(b.dataset.commandTool)});
}
$('command-search').oninput=renderCommands;
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='p'){e.preventDefault();$('open-command-center').click()}});
document.addEventListener('click',e=>{if(!e.target.closest('.card-menu')&&!e.target.closest('[data-menu]'))closeMenus()});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('search').focus()}if(e.key==='Escape'){closeModal();closeDetails();document.querySelectorAll('.modal').forEach(m=>m.classList.add('hidden'));closeMenus()}});load().then(async()=>{const params=new URLSearchParams(location.search),view=params.get('view');if(view==='database'){document.body.classList.add('database-page-mode');$('database-modal').classList.remove('hidden');await renderDatabaseManager();await refreshPortableStatus()}else if(view==='health')$('library-health').click();else if(view==='links')$('check-links').click();else if(view==='categories')$('category-manager').click();else if(view==='restore')$('restore-backup').click();else if(view==='defaults')$('restore-defaults').click();else if(view==='dedupe')$('dedupe-library').click();else if(view==='compare')$('compare-libraries').click();else if(view==='viewLocal'||view==='viewRemote'||view==='viewUnified'){state.source=view==='viewLocal'?'local':view==='viewRemote'?'remote':'';$('source-filter').value=state.source;render();}}).catch(err=>{console.error('Charlie MJ initialization failed:',err);const grid=$('grid');if(grid){grid.innerHTML='';$('empty').classList.remove('hidden');$('empty').textContent='The library could not be initialized. Your saved data has not been deleted. Open Settings → Database & Storage or reload the extension. Details: '+String(err?.message||err)}});
